  element.style.animation = 'none';
}

// Слушать изменения настройки
prefersReducedMotion.addEventListener('change', (e) => {
  if (e.matches) {
    // Отключить анимации
  } else {
    // Включить анимации
  }
});

.element {
  animation-name: fade-in;
  animation-duration: 0.5s;
  animation-timing-function: ease;
  animation-delay: 0.2s;
  animation-iteration-count: 3;  /* infinite для бесконечной */
  animation-direction: alternate;  /* normal, reverse, alternate, alternate-reverse */
  animation-fill-mode: forwards;  /* none, forwards, backwards, both */
  animation-play-state: running;  /* paused */

  /* Шортхэнд */
  animation: fade-in 0.5s ease 0.2s 3 alternate forwards;
}

.element {
  animation: move 1s, scale 1s;

  /* replace — по умолчанию, последняя анимация побеждает */
  /* add — анимации складываются (transform) */
  /* accumulate — как add, но для filter и др. */
  animation-composition: add;
}

.card {
  animation:
    float 3s ease-in-out infinite,
    rotate 10s linear infinite;
  animation-composition: add;  /* Обе работают одновременно! */
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes rotate {
  to { transform: rotate(360deg); }
}

.btn {
  transition-property: background, transform, opacity;
  transition-duration: 0.2s;
  transition-timing-function: ease;
  transition-delay: 0s;

  /* Шортхэнд */
  transition: background 0.2s, transform 0.2s, opacity 0.2s;

  /* transition-behavior: allow-discrete — для анимации display */
  transition: display 0.3s allow-discrete;
}

.btn:hover {
  background: oklch(0.55 0.22 264);
  transform: scale(1.05);
  opacity: 0.9;
}

.modal {
  display: none;
  opacity: 0;
  transition: opacity 0.3s, display 0.3s allow-discrete;
}

/* Начальное состояние перед появлением */
@starting-style {
  .modal {
    opacity: 0;
    transform: scale(0.9);
  }
}

.modal.is-open {
  display: block;
  opacity: 1;
  transform: scale(1);
}

.perf-card {
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.5rem;
  border: 1px solid oklch(0.88 0.006 285);
  border-radius: 1rem;
  background: white;

  /* Дешёвые анимации — только transform и opacity */
  transition:
    transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.3s ease,
    border-color 0.3s ease;

  will-change: auto;  /* Сбрасываем по умолчанию */
}

.perf-card:hover {
  will-change: transform, box-shadow;  /* Включаем перед ховером */
  transform: translateY(-4px);
  box-shadow: 0 12px 28px rgb(0 0 0 / 0.1);
  border-color: oklch(0.62 0.22 264);
}

.perf-card:focus-within {
  outline: 3px solid oklch(0.62 0.22 264);
  outline-offset: 2px;
}

.perf-card:active {
  transform: translateY(-2px) scale(0.98);
}

/* Сбрасываем will-change после взаимодействия */
.perf-card:not(:hover):not(:focus-within) {
  will-change: auto;
}

.perf-card__media {
  position: relative;
  aspect-ratio: 16 / 9;
  width: 100%;
  background: oklch(0.97 0.001 285);
  border-radius: 0.75rem;
  overflow: hidden;
}

.perf-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;

  /* Дешёвая анимация масштабирования при ховере */
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.perf-card:hover .perf-card__img {
  transform: scale(1.05);
}

.perf-card__badge {
  position: absolute;
  top: 0.5rem;
  left: 0.5rem;
  background: oklch(0.65 0.22 20);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
}

/* Маска для изображения (опциональный эффект) */
.perf-card__img--masked {
  -webkit-mask-image: linear-gradient(black 80%, transparent 100%);
  mask-image: linear-gradient(black 80%, transparent 100%);
}

/* Фильтр на изображение — используй осторожно, может быть дорого */
.perf-card:hover .perf-card__img {
  filter: brightness(1.1);
}

/* Анимация входа */
@keyframes card-appear {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.perf-card {
  animation: card-appear 0.5s ease forwards;
  animation-delay: 0.1s;
  opacity: 0;  /* Начальное состояние для JS или CSS */
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  .perf-card,
  .perf-card__img {
    transition: none;
    animation: none;
  }

  .perf-card:hover {
    transform: none;
    box-shadow: none;
  }

  .perf-card:hover .perf-card__img {
    transform: none;
    filter: none;
  }
}

/* Forced colors (Windows High Contrast) */
@media (forced-colors: active) {
  .perf-card {
    border: 1px solid CanvasText;
    background: Canvas;
  }

  .perf-card__badge {
    background: Highlight;
    color: HighlightText;
  }
}
